/* @socom-skeleton body FireValidityCheck__12CZProjectileFv */
bool CZProjectile::FireValidityCheck()
{
	// Created projectiles are validated by the server only.
	if (theNetwork.m_bNetwork)
		return false;
	
	if (!m_weapon)
		return false;

	if (!m_weapon->IsDirectFire())
		return false;

	return true;
}

